import React, { useState, useEffect, useRef } from 'react';
import styles from './TerminalCursor.module.css';

const TerminalCursor = () => {
  const [trails, setTrails] = useState([]);
  const [isTouchDevice, setIsTouchDevice] = useState(false);
  const frameRef = useRef();
  const maxTrails = 5;

  useEffect(() => {
    if ('ontouchstart' in window || navigator.maxTouchPoints > 0) {
      setIsTouchDevice(true);
      return;
    }

    let mouseX = 0;
    let mouseY = 0;

    const handleMouseMove = (e) => {
      mouseX = e.clientX;
      mouseY = e.clientY;
    };

    const animate = () => {
      setTrails(prev => {
        const newTrail = { x: mouseX, y: mouseY, id: Date.now() + Math.random() };
        const updated = [...prev, newTrail];
        if (updated.length > maxTrails) {
          return updated.slice(-maxTrails);
        }
        return updated;
      });
      frameRef.current = requestAnimationFrame(animate);
    };

    window.addEventListener('mousemove', handleMouseMove);
    frameRef.current = requestAnimationFrame(animate);

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      if (frameRef.current) {
        cancelAnimationFrame(frameRef.current);
      }
    };
  }, []);

  if (isTouchDevice) return null;

  return (
    <>
      {trails.map((trail, index) => (
        <div
          key={trail.id}
          className={styles.trail}
          style={{
            left: `${trail.x}px`,
            top: `${trail.y}px`,
            opacity: (index + 1) / maxTrails * 0.4,
            transform: `translate(-50%, -50%) scale(${1 - index * 0.1})`,
            transition: 'all 0.05s linear'
          }}
        >
          {index === trails.length - 1 ? '█' : '░'}
        </div>
      ))}
    </>
  );
};

export default TerminalCursor;
